def split_csv(line):
    fields = []
    i = 0

    while i < len(line):
        # Start of a new field
        if line[i] == '"':
            # Quoted field
            i += 1
            field = []
            while i < len(line):
                if line[i] == '"':
                    # Check if it's a doubled quote
                    if i + 1 < len(line) and line[i + 1] == '"':
                        field.append('"')
                        i += 2
                    else:
                        # End of quoted field
                        i += 1
                        # Check what follows
                        if i < len(line):
                            if line[i] == ',':
                                i += 1
                            else:
                                # Invalid: closing quote not followed by comma or EOL
                                return None
                        fields.append(''.join(field))
                        break
                else:
                    field.append(line[i])
                    i += 1
            else:
                # Reached end of line without finding closing quote
                return None
        else:
            # Unquoted field
            field = []
            while i < len(line) and line[i] != ',':
                if line[i] == '"':
                    # Double quote in unquoted field is invalid
                    return None
                field.append(line[i])
                i += 1

            fields.append(''.join(field))

            # Skip the comma if present
            if i < len(line) and line[i] == ',':
                i += 1

    return fields

